package io.aetheris.orchestrator.api;import io.aetheris.orchestrator.trading.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/orchestrator/stage9/trading") public class Stage9TradingController {private final MultiSourceMarketDataBook market;private final AdvancedBacktestService backtests;private final PaperPortfolioAnalyticsService portfolio;private final Stage9PaperTradingService paper;public Stage9TradingController(MultiSourceMarketDataBook market,AdvancedBacktestService backtests,PaperPortfolioAnalyticsService portfolio,Stage9PaperTradingService paper){this.market=market;this.backtests=backtests;this.portfolio=portfolio;this.paper=paper;}@PostMapping("/market-data") public MarketDataSnapshot market(@RequestBody MarketDataSnapshot s){return market.ingest(s);}@GetMapping("/market-consensus/{symbol}") public MarketConsensus consensus(@PathVariable String symbol,@RequestParam(defaultValue="2") int minSources,@RequestParam(defaultValue="60") long maxAgeSeconds,@RequestParam(defaultValue="15") long maxClockSkewSeconds,@RequestParam(defaultValue="0.75") double maxDivergencePct){return market.consensus(symbol,minSources,maxAgeSeconds,maxClockSkewSeconds,maxDivergencePct);}@GetMapping("/market-consensus/evidence") public List<MarketConsensusEvidenceEntity> evidence(){return market.recentEvidence();}@PostMapping("/backtests") public AdvancedBacktestResultEntity backtest(@RequestBody AdvancedBacktestRequest r){return backtests.run(r);}@GetMapping("/backtests") public List<AdvancedBacktestResultEntity> backtests(){return backtests.recent();}@PostMapping("/paper/open/{signalId}") public PaperExecutionResult open(@PathVariable UUID signalId,@RequestParam String symbol,@RequestParam(defaultValue="2") int minSources,@RequestParam(defaultValue="60") long maxAgeSeconds,@RequestParam(defaultValue="15") long maxClockSkewSeconds,@RequestParam(defaultValue="0.75") double maxDivergencePct){return paper.openConsensus(signalId,symbol,minSources,maxAgeSeconds,maxClockSkewSeconds,maxDivergencePct);}@PostMapping("/paper/mark") public PaperEquitySnapshotEntity mark(@RequestParam(defaultValue="2") int minSources,@RequestParam(defaultValue="60") long maxAgeSeconds,@RequestParam(defaultValue="15") long maxClockSkewSeconds,@RequestParam(defaultValue="0.75") double maxDivergencePct){return portfolio.mark(minSources,maxAgeSeconds,maxClockSkewSeconds,maxDivergencePct);}@GetMapping("/paper/equity") public List<PaperEquitySnapshotEntity> equity(){return portfolio.history();}@GetMapping("/paper/correlations") public List<PositionCorrelation> correlations(@RequestParam(defaultValue="2") int minSources,@RequestParam(defaultValue="60") long maxAgeSeconds,@RequestParam(defaultValue="15") long maxClockSkewSeconds,@RequestParam(defaultValue="0.75") double maxDivergencePct){return portfolio.correlations(minSources,maxAgeSeconds,maxClockSkewSeconds,maxDivergencePct);}@GetMapping("/testnet-plan") public TestnetExchangePlan testnet(){return TestnetExchangePlan.current();}}
